const item = $input.first().json;

const name  = item['Full Name'] || item['full_name'] || item['Name'] || 'Unknown';
const email = item['Email']     || item['email']     || '';

const resumeUrl = item['Resume'] || item['CV'] || item['Upload your resume'] || item['Upload Resume'] || '';

if (!name || name === 'Unknown') throw new Error('Missing Full Name in sheet row');
if (!email) throw new Error('Missing Email in sheet row');
if (!resumeUrl) throw new Error('Missing resume file URL in sheet row. Check your column name matches exactly.');

let fileId = '';
const matchV = resumeUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
const matchO = resumeUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
const matchS = resumeUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);

if (matchV) fileId = matchV[1];
else if (matchO) fileId = matchO[1];
else if (matchS) fileId = matchS[1];
else throw new Error('Could not extract Drive file ID from URL: ' + resumeUrl);

return [{
  json: {
    candidate_name: String(name).trim(),
    email: String(email).trim().toLowerCase(),
    file_id: fileId,
    resume_url: resumeUrl
  }
}];

const item = $input.first();
const raw = item.json;
const body = raw.body || raw;

const name = body['Full Name'] || body.full_name || body.name || body.candidate_name || 'Unknown';
const email = body['Email'] || body.email || '';

if (!name || name === 'Unknown') throw new Error('Missing required field: Full Name');
if (!email) throw new Error('Missing required field: Email');

return [{
  json: {
    candidate_name: String(name).trim(),
    email: String(email).trim().toLowerCase()
  }
}];

const items = $input.all();
let aiResponse = '';
let alreadyParsed = null;

for (const item of items) {
  if (item.json.score !== undefined || item.json.strengths !== undefined) {
    alreadyParsed = item.json;
  }
  if (item.json.text && typeof item.json.text === 'string') aiResponse = item.json.text;
  else if (item.json.output && typeof item.json.output === 'string') aiResponse = item.json.output;
}

// Pull form name + email — works for BOTH triggers
let candidateName = 'Unknown';
let candidateEmail = 'Unknown';

// Try n8n form trigger path first
try {
  const formData = $('Validate & Extract Input').first().json;
  if (formData.candidate_name) candidateName = formData.candidate_name;
  if (formData.email) candidateEmail = formData.email;
} catch(e) {}

// Fallback: try Google Sheets trigger path
if (candidateName === 'Unknown' || candidateEmail === 'Unknown') {
  try {
    const sheetData = $('Extract Sheet Row Data').first().json;
    if (sheetData.candidate_name && candidateName === 'Unknown') candidateName = sheetData.candidate_name;
    if (sheetData.email && candidateEmail === 'Unknown') candidateEmail = sheetData.email;
  } catch(e) {}
}

// Pull phone + email + location from CV via Candidate Details node
let phoneFromCV = 'Not found';
let emailFromCV = 'Not found';
let locationFromCV = 'Not found';
let appliedRole = 'Not found';
try {
  const detailsRaw = $('Candidate Details').first().json.text || $('Candidate Details').first().json.output || '';
  const cleaned = detailsRaw.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    const details = JSON.parse(match[0]);
    phoneFromCV    = details.phone         || 'Not found';
    emailFromCV    = details.email_from_cv || 'Not found';
    locationFromCV = details.location      || 'Not found';
    appliedRole    = details.applied_role  || 'Not found';
    if (candidateName === 'Unknown' && details.candidate_name) candidateName = details.candidate_name;
  }
} catch(e) {
  phoneFromCV = 'Parse error: ' + e.message;
}

// Parse HR Expert evaluation JSON
let parsedData = {};
if (alreadyParsed) {
  parsedData = alreadyParsed;
} else {
  if (aiResponse) {
    aiResponse = aiResponse.replace(/```json/gi, '').replace(/```/g, '').trim();
    const match = aiResponse.match(/\{[\s\S]*\}/);
    if (match) aiResponse = match[0];
  } else {
    aiResponse = '{}';
  }
  try {
    parsedData = JSON.parse(aiResponse);
  } catch(e) {
    // ADDED disqualification_reason here for safe error handling
    parsedData = {
      score: null,
      strengths: 'Parse Error: ' + e.message,
      gaps: 'Check debug_raw_text column for raw AI output.',
      verdict: 'Error',
      summary_evaluation: 'Failed to parse AI response.',
      disqualification_reason: 'Error: Could not parse response' 
    };
  }
}

return [{
  json: {
    candidate_name:     candidateName,
    email:              candidateEmail,
    email_from_cv:      emailFromCV,
    phone:              phoneFromCV,
    location:           locationFromCV,
    applied_role:       appliedRole,

    // ADDED checks for different casing from the LLM just in case
    disqualification_reason: parsedData.disqualification_reason || parsedData.disqualificationReason || parsedData.Disqualification_Reason || '',

    score:              parsedData.score              || parsedData.Score              || null,
    strengths:          parsedData.strengths          || parsedData.Strengths          || 'Not provided',
    gaps:               parsedData.gaps               || parsedData.Gaps               || 'Not provided',
    verdict:            parsedData.verdict            || parsedData.Verdict            || 'Unknown',
    summary_evaluation: parsedData.summary_evaluation || parsedData.summary            || 'Not provided',
    evaluated_at:       new Date().toISOString(),
    debug_raw_text:     aiResponse,
  }
}];
